/**
 * `read_ai_layer_bounds` against After Effects' own artwork boxes.
 *
 * Both fixtures are AE 2026 imports, so these tests compare py_aep's measuring
 * pass against the real thing rather than against expectations:
 *
 * - `ai_bounds_probe.aep` is a `COMP_CROPPED_LAYERS` import of the hand-built
 *   `ai_bounds_probe.pdf` (one layer per rule, regenerated by
 *   `scripts/make_ai_bounds_probe.py`);
 * - `ai_choose_layer1_size.aep` is a Choose Layer + Layer Size **footage** import
 *   of a real Illustrator file, which is what `layer_dimensions="layer"`
 *   actually produces. The two paths store the same box, which is what licenses
 *   using the cropped comp as the oracle;
 * - `std14_probe.aep` is a `COMP_CROPPED_LAYERS` import of `std14_probe.pdf`,
 *   whose every layer draws from a font dictionary carrying neither `/Widths`
 *   nor a `/FontDescriptor`, so AE has nothing but its built-in standard-14
 *   metrics to measure with. Two layers per font draw a single glyph, and a
 *   third draws every tabulated code at once, so its width is the sum of all 95
 *   advances.
 */

import { describe, expect, test } from "bun:test";
import { Path, getOrThrow, len, lruCache, assert, valueEquals, setWarningHandler, zip } from "../../src/pyrt/index.ts";

import type { Box } from "../../src/py_aep/resolvers/ai_bounds.ts";
import { EMPTY_BOX, footageSize, readAiLayerBounds } from "../../src/py_aep/resolvers/ai_bounds.ts";
import { readAiLayers } from "../../src/py_aep/resolvers/ai_layers.ts";
import { aiLayerOptiBoxes, parseProject } from "../helpers.ts";
import { approx } from "../support/pytest.ts";
import { round } from "../support/python.ts";

// `Path(__file__).parent.parent.parent / "samples" / ...` in the Python source.
const ASSETS = new Path(import.meta.dir, "..", "..", "samples", "assets");
const IMPORT_DIR = new Path(import.meta.dir, "..", "..", "samples", "models", "import");

const PROBE_PDF = ASSETS.div("ai_bounds_probe.pdf");
const PROBE_AEP = IMPORT_DIR.div("ai_bounds_probe.aep");

const STD14_PDF = ASSETS.div("std14_probe.pdf");
const STD14_AEP = IMPORT_DIR.div("std14_probe.aep");

/**
 * After Effects' own arithmetic differs from ours in the last fixed-point
 * step or two, so a handful of layers land within a couple of 1/65536
 * quanta (0.00003pt) rather than exactly. Every derived footage dimension
 * still matches, which is what the stored box is actually used for.
 */
const QUANTUM = 1 / 65536;
const TOLERANCE = 3 * QUANTUM;

/** After Effects' own artwork box and footage size, per layer name. */
// `lru_cache` keys by argument identity while Python's `Path` hashes by value, so the cache is keyed on the path string.
const _aeLayerBoxesCached = lruCache((aep: string): Map<string, [number[], number, number]> =>
  aiLayerOptiBoxes(parseProject(new Path(aep))),
);
function _aeLayerBoxes(aep: Path): Map<string, [number[], number, number]> {
  return _aeLayerBoxesCached(String(aep));
}

/** Every layer's measured box, read and measured once per file. */
const _measuredCached = lruCache((path_: string): Map<string, Box | null> => {
  const path = new Path(path_);
  const data = path.readBytes();
  // Python wraps both reads in `warnings.catch_warnings()` with `simplefilter("ignore", UserWarning)`.
  const previous = setWarningHandler(() => {});
  let names: string[];
  let bounds: (Box | null)[];
  try {
    names = readAiLayers(path, data);
    bounds = readAiLayerBounds(path, data);
  } finally {
    setWarningHandler(previous);
  }
  return new Map(zip(names, bounds));
});
function _measured(path: Path): Map<string, Box | null> {
  return _measuredCached(String(path));
}

function _probeLayers(): string[] {
  return [..._aeLayerBoxes(PROBE_AEP).keys()];
}

function _std14Layers(): string[] {
  return [..._aeLayerBoxes(STD14_AEP).keys()];
}

describe("TestProbeFixture", () => {
  /** Every rule, against the AE import of the hand-built probe PDF. */

  test("test_every_layer_is_measured", () => {
    const measured = _measured(PROBE_PDF);
    expect(valueEquals(new Set(measured.keys()), new Set(_aeLayerBoxes(PROBE_AEP).keys()))).toBe(true);
    expect(len(measured)).toBe(22);
  });

  test.each(_probeLayers())("test_box_matches_after_effects[%#]", (layer: string) => {
    const [aeBox, _width, _height] = getOrThrow(_aeLayerBoxes(PROBE_AEP), layer);
    const box = getOrThrow(_measured(PROBE_PDF), layer);
    const expected = box == null ? EMPTY_BOX : box;
    expect(approx(expected, aeBox, { abs: TOLERANCE })).toBe(true);
  });

  test.each(_probeLayers())("test_derived_footage_size_matches_after_effects[%#]", (layer: string) => {
    const [_box, width, height] = getOrThrow(_aeLayerBoxes(PROBE_AEP), layer);
    expect(valueEquals(footageSize(getOrThrow(_measured(PROBE_PDF), layer)), [width, height])).toBe(true);
  });

  test("test_layer_with_no_artwork_measures_empty", () => {
    expect(getOrThrow(_measured(PROBE_PDF), "q_empty")).toBe(null);
  });

  test("test_most_layers_are_byte_exact", () => {
    // A guard on the float divergence above: if a change starts rounding
    // differently across the board, this drops well below the current 19.
    const ae = _aeLayerBoxes(PROBE_AEP);
    const measured = _measured(PROBE_PDF);
    let exact = 0;
    for (const [name, [aeBox, _w, _h]] of ae) {
      const box = getOrThrow(measured, name);
      const rawPy = (box == null ? EMPTY_BOX : box).map((v) => round(v * 65536));
      const rawAe = aeBox.map((v) => round(v * 65536));
      exact += valueEquals(rawPy, rawAe) ? 1 : 0;
    }
    expect(exact >= 19).toBe(true);
  });
});

describe("TestIllustratorFootageFixture", () => {
  /** The real-Illustrator case, against AE's Layer Size footage import. */

  test("test_box_matches_the_footage_import", () => {
    // `ai.ai`'s Calque 1 is a bezier clip filled by a shading plus a
    // rotated five-glyph text run: its box takes the minimum corner from
    // the unpadded text and the maximum from the padded path, which is
    // what pins the expansion as per-contribution.
    const ae = _aeLayerBoxes(IMPORT_DIR.div("ai_choose_layer1_size.aep"));
    const box = getOrThrow(_measured(ASSETS.div("ai.ai")), "Calque 1");
    expect(approx(box, getOrThrow(ae, "Calque 1")[0], { abs: TOLERANCE })).toBe(true);
    expect(valueEquals(footageSize(box), [482, 437])).toBe(true);
  });

  test("test_empty_layer_matches_the_footage_import", () => {
    const ae = _aeLayerBoxes(IMPORT_DIR.div("ai_choose_layer_size.aep"));
    expect(approx(getOrThrow(ae, "Calque 2")[0], EMPTY_BOX, { abs: TOLERANCE })).toBe(true);
    expect(getOrThrow(_measured(ASSETS.div("ai.ai")), "Calque 2")).toBe(null);
  });

  test("test_cropped_comp_and_footage_paths_agree", () => {
    // The cropped-comp import is the oracle the rules were measured
    // against; this is the check that licenses it.
    const cropped = _aeLayerBoxes(IMPORT_DIR.div("ai_comp.aep"));
    const footage = _aeLayerBoxes(IMPORT_DIR.div("ai_choose_layer.aep"));
    // Both are Document Size imports of the same file, so both store the
    // full-page box.
    expect(approx(getOrThrow(cropped, "Calque 1")[0], [0.0, 0.0, 612.0, 792.0])).toBe(true);
    expect(approx(getOrThrow(footage, "Calque 2")[0], [0.0, 0.0, 612.0, 792.0])).toBe(true);
  });
});

describe("TestStandard14Fixture", () => {
  /**
   * The built-in font metrics, against AE's import of the font probe.
   *
   * Every layer draws from a font dictionary with no `/Widths` and no
   * `/FontDescriptor`, so nothing in the file says how wide or how tall the
   * text is and only `data.std14_metrics` can supply it.
   */

  test("test_every_layer_is_measured", () => {
    const measured = _measured(STD14_PDF);
    expect(valueEquals(new Set(measured.keys()), new Set(_aeLayerBoxes(STD14_AEP).keys()))).toBe(true);
    expect(len(measured)).toBe(48);
  });

  test.each(_std14Layers())("test_box_matches_after_effects[%#]", (layer: string) => {
    const [aeBox, _width, _height] = getOrThrow(_aeLayerBoxes(STD14_AEP), layer);
    expect(approx(getOrThrow(_measured(STD14_PDF), layer), aeBox, { abs: TOLERANCE })).toBe(true);
  });

  test.each(_std14Layers())("test_derived_footage_size_matches_after_effects[%#]", (layer: string) => {
    const [_box, width, height] = getOrThrow(_aeLayerBoxes(STD14_AEP), layer);
    expect(valueEquals(footageSize(getOrThrow(_measured(STD14_PDF), layer)), [width, height])).toBe(true);
  });

  test("test_every_layer_is_byte_exact", () => {
    // Unlike the geometry probe, nothing here goes through the expansion
    // arithmetic that costs the odd fixed-point quantum, so these should
    // match After Effects to the bit.
    const ae = _aeLayerBoxes(STD14_AEP);
    const measured = _measured(STD14_PDF);
    for (const [name, [aeBox, _w, _h]] of ae) {
      const box = getOrThrow(measured, name);
      assert(box != null);
      const rawPy = box.map((v) => round(v * 65536));
      const rawAe = aeBox.map((v) => round(v * 65536));
      assert(valueEquals(rawPy, rawAe), name);
    }
  });

  test("test_aliases_measure_as_their_standard_14_face", () => {
    // AE resolves /Arial and /TimesNewRoman onto its built-in Helvetica
    // and Times-Roman metrics rather than onto the installed face, which
    // is the evidence that the tables are not host-specific.
    const measured = _measured(STD14_PDF);
    for (const [alias, face] of [
      ["Arial", "Helvetica"],
      ["TimesNewRoman", "Times-Roman"],
    ]) {
      for (const prefix of ["A", "B", "C"]) {
        const aliasBox = getOrThrow(measured, `${prefix}_${alias}`);
        const faceBox = getOrThrow(measured, `${prefix}_${face}`);
        assert(aliasBox != null && faceBox != null);
        expect(
          approx(
            [aliasBox[2] - aliasBox[0], aliasBox[3] - aliasBox[1]],
            [faceBox[2] - faceBox[0], faceBox[3] - faceBox[1]],
          ),
        ).toBe(true);
      }
    }
  });
});
